BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';
ALTER TABLE public.pub_native_account_meta ADD COLUMN disconnected boolean NOT NULL DEFAULT false,ADD COLUMN disconnected_at timestamptz;
CREATE TABLE public.pub_native_media_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id varchar(36) NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,asset_id uuid NOT NULL REFERENCES public.pub3_assets(id),collection_id uuid NOT NULL REFERENCES public.pub2_collections(id),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),archived boolean NOT NULL DEFAULT false,title text NOT NULL DEFAULT '',is_copy boolean NOT NULL DEFAULT false,source_entry_id uuid REFERENCES public.pub_native_media_entries(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX native_original_media_once ON public.pub_native_media_entries(owner_id,asset_id,collection_id) WHERE NOT is_copy AND NOT archived;
CREATE TABLE public.pub_native_media_usage_refs(owner_id varchar(36) NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,draft_id uuid NOT NULL,draft_version integer NOT NULL,media_id uuid NOT NULL,media_entry_id uuid NOT NULL REFERENCES public.pub_native_media_entries(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(draft_id,draft_version,media_id),FOREIGN KEY(draft_id,draft_version) REFERENCES public.pub2_draft_versions(draft_id,version) ON DELETE CASCADE);
CREATE TABLE public.pub_native_core_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id varchar(36) NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,request_key text NOT NULL,request_hash text NOT NULL,request_payload jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,request_key));
CREATE TABLE public.pub_native_core_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id varchar(36) NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,request_id uuid NOT NULL REFERENCES public.pub_native_core_requests(id),kind text NOT NULL,safe_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['pub_native_core_requests','pub_native_core_events','pub_native_media_entries','pub_native_media_usage_refs'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated,service_role',t);EXECUTE format('GRANT SELECT ON TABLE public.%I TO service_role',t);END LOOP;END$$;
CREATE TRIGGER native_core_request_immutable BEFORE UPDATE OR DELETE ON public.pub_native_core_requests FOR EACH ROW EXECUTE FUNCTION public.native_metadata_history_guard();
CREATE TRIGGER native_core_event_immutable BEFORE UPDATE OR DELETE ON public.pub_native_core_events FOR EACH ROW EXECUTE FUNCTION public.native_metadata_history_guard();
CREATE TRIGGER native_media_usage_ref_immutable BEFORE UPDATE OR DELETE ON public.pub_native_media_usage_refs FOR EACH ROW EXECUTE FUNCTION public.native_metadata_history_guard();
CREATE FUNCTION public.native_assert_account_connected() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$DECLARE v_owner text;v_id uuid;v_kind text;BEGIN
 IF TG_TABLE_NAME='pub3_operations' THEN
  IF NEW.kind<>'publish' THEN RETURN NEW;END IF;IF TG_OP='UPDATE' THEN IF NOT(OLD.grant_used IS FALSE AND NEW.grant_used IS TRUE) THEN RETURN NEW;END IF;END IF;
  v_owner:=NEW.owner_id;v_id:=(NEW.snapshot->'binding'->>'id')::uuid;v_kind:='official';
 ELSIF TG_TABLE_NAME='pub2_attempts' THEN v_owner:=NEW.user_id;v_id:=(NEW.snapshot->'target'->>'accountId')::uuid;v_kind:='browser';IF v_id::text IS DISTINCT FROM NEW.snapshot->'account'->>'id' THEN RAISE EXCEPTION 'PUBLISH_V2_ACCOUNT_CHANGED';END IF;
 ELSE v_owner:=NEW.user_id;v_id:=NEW.account_id;v_kind:='browser';END IF;
 PERFORM public.pub_assert_actor(v_owner);
 IF v_id IS NULL OR EXISTS(SELECT 1 FROM public.pub_native_account_meta WHERE owner_id=v_owner AND account_kind=v_kind AND account_id=v_id AND disconnected) THEN
  IF TG_TABLE_NAME='pub3_operations' THEN RAISE EXCEPTION 'PUBLISH_API_BINDING_CHANGED';ELSIF TG_TABLE_NAME='pub2_attempts' THEN RAISE EXCEPTION 'PUBLISH_V2_ACCOUNT_CHANGED';ELSE RAISE EXCEPTION 'PUBLISH_ACCOUNT_NOT_FOUND';END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER native_connected_v1_claim BEFORE INSERT ON public.pub_tasks FOR EACH ROW EXECUTE FUNCTION public.native_assert_account_connected();
CREATE TRIGGER native_connected_v2_claim BEFORE INSERT ON public.pub2_attempts FOR EACH ROW EXECUTE FUNCTION public.native_assert_account_connected();
CREATE TRIGGER native_connected_v3_claim BEFORE INSERT OR UPDATE OF grant_used ON public.pub3_operations FOR EACH ROW EXECUTE FUNCTION public.native_assert_account_connected();
CREATE FUNCTION public.native_core_usage_facts(p_owner text,p_draft_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,pg_temp AS $$
 WITH official AS (
 SELECT o.id,o.revision,o.outcome,o.dispatch_state,o.grant_used,o.work_id,o.work_link FROM public.pub3_operations o WHERE o.owner_id=p_owner AND o.kind='publish' AND (o.snapshot->'intent'->>'draftId'=p_draft_id::text OR EXISTS(SELECT 1 FROM public.pub_native_publish_plans p CROSS JOIN LATERAL jsonb_array_elements(p.result_mapping) g CROSS JOIN LATERAL jsonb_array_elements(g->'officialTargets') t WHERE p.owner_id=p_owner AND p.request_payload->>'sourceDraftId'=p_draft_id::text AND t->'intent'->>'id'=o.subject_id::text))
 ),browser AS (
 SELECT a.id,r.has_receipt,r.payload FROM public.pub2_attempts a LEFT JOIN LATERAL (SELECT count(*)>0 has_receipt,min(e.payload::text)::jsonb payload FROM public.pub2_attempt_events e WHERE e.attempt_id=a.id AND e.user_id=p_owner AND e.kind='browser_report') r ON true WHERE a.user_id=p_owner AND (a.snapshot->>'draftId'=p_draft_id::text OR EXISTS(SELECT 1 FROM public.pub_native_publish_plans p CROSS JOIN LATERAL jsonb_array_elements(p.result_mapping) g WHERE p.owner_id=p_owner AND p.request_payload->>'sourceDraftId'=p_draft_id::text AND g->'batch'->>'id'=a.batch_id::text))
 ),facts AS(SELECT jsonb_build_object('official',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY id) FROM official o),'[]'::jsonb),'browser',coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY id) FROM browser b),'[]'::jsonb)) value)
 SELECT jsonb_build_object('draftId',p_draft_id,'confirmedUses',(SELECT count(*) FROM official WHERE outcome='published'),'browserReportedUses',(SELECT count(*) FROM browser WHERE payload->'success'='true'::jsonb),'unknownUses',(SELECT count(*) FROM official WHERE outcome='unknown' OR grant_used AND outcome NOT IN ('published','failed','cancelled'))+(SELECT count(*) FROM browser WHERE NOT has_receipt),'usageFingerprint',encode(sha256(convert_to(value::text,'UTF8')),'hex')) FROM facts
$$;
CREATE FUNCTION public.read_native_usage_facts(p_user_id text,p_draft_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE v_id uuid;v_result jsonb:='[]';BEGIN
 PERFORM public.pub_assert_actor(p_user_id);IF coalesce(cardinality(p_draft_ids),0) NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM unnest(p_draft_ids) x WHERE x IS NULL) OR cardinality(p_draft_ids)<>(SELECT count(DISTINCT x) FROM unnest(p_draft_ids) x) THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
 FOREACH v_id IN ARRAY p_draft_ids LOOP PERFORM 1 FROM public.pub2_drafts WHERE id=v_id AND user_id=p_user_id;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;v_result:=v_result||jsonb_build_array(public.native_core_usage_facts(p_user_id,v_id));END LOOP;RETURN v_result;
END$$;
CREATE FUNCTION public.native_core_media_usage_facts(p_owner text,p_entry_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,pg_temp AS $$
 WITH entry AS(SELECT * FROM public.pub_native_media_entries WHERE id=p_entry_id AND owner_id=p_owner),refs AS(SELECT * FROM public.pub_native_media_usage_refs WHERE owner_id=p_owner AND media_entry_id=p_entry_id),official AS(
 SELECT o.id,o.revision,o.outcome,o.dispatch_state,o.grant_used FROM public.pub3_operations o WHERE o.owner_id=p_owner AND o.kind='publish' AND EXISTS(SELECT 1 FROM refs r WHERE (o.snapshot->'intent'->>'draftId'=r.draft_id::text AND o.snapshot->'intent'->>'draftVersion'=r.draft_version::text OR EXISTS(SELECT 1 FROM public.pub_native_publish_plans p CROSS JOIN LATERAL jsonb_array_elements(p.result_mapping) g CROSS JOIN LATERAL jsonb_array_elements(g->'officialTargets') t WHERE p.owner_id=p_owner AND p.request_payload->>'sourceDraftId'=r.draft_id::text AND p.request_payload->>'sourceDraftVersion'=r.draft_version::text AND t->'intent'->>'id'=o.subject_id::text)) AND EXISTS(SELECT 1 FROM jsonb_array_elements(o.snapshot->'assets') actual WHERE actual->>'id'=(SELECT asset_id::text FROM entry) AND actual->>'mediaId'=r.media_id::text) AND (o.snapshot->'intent'->'mediaIds' ? r.media_id::text OR o.snapshot->'intent'->>'coverMediaId'=r.media_id::text))
 ),browser AS(
 SELECT a.id,q.has_receipt,q.payload FROM public.pub2_attempts a LEFT JOIN LATERAL(SELECT count(*)>0 has_receipt,min(e.payload::text)::jsonb payload FROM public.pub2_attempt_events e WHERE e.attempt_id=a.id AND e.user_id=p_owner AND e.kind='browser_report') q ON true WHERE a.user_id=p_owner AND EXISTS(SELECT 1 FROM refs r WHERE (a.snapshot->>'draftId'=r.draft_id::text AND a.snapshot->>'draftVersion'=r.draft_version::text OR EXISTS(SELECT 1 FROM public.pub_native_publish_plans p CROSS JOIN LATERAL jsonb_array_elements(p.result_mapping) g WHERE p.owner_id=p_owner AND p.request_payload->>'sourceDraftId'=r.draft_id::text AND p.request_payload->>'sourceDraftVersion'=r.draft_version::text AND g->'batch'->>'id'=a.batch_id::text)) AND EXISTS(SELECT 1 FROM public.pub_native_draft_meta actual_meta CROSS JOIN LATERAL jsonb_array_elements(actual_meta.payload->'media') actual WHERE actual_meta.owner_id=p_owner AND actual_meta.draft_id::text=a.snapshot->>'draftId' AND actual_meta.draft_version::text=a.snapshot->>'draftVersion' AND actual->>'assetId'=(SELECT asset_id::text FROM entry) AND actual->>'mediaId'=r.media_id::text) AND (a.snapshot->'target'->'mediaIds' ? r.media_id::text OR NOT(a.snapshot->'target' ? 'mediaIds') AND EXISTS(SELECT 1 FROM jsonb_array_elements(a.snapshot->'draft'->'media') m WHERE m->>'id'=r.media_id::text AND m->>'role'<>'cover') OR a.snapshot->'target'->>'coverMediaId'=r.media_id::text OR NOT(a.snapshot->'target' ? 'mediaIds') AND NOT(a.snapshot->'target' ? 'coverMediaId') AND EXISTS(SELECT 1 FROM jsonb_array_elements(a.snapshot->'draft'->'media') m WHERE m->>'id'=r.media_id::text AND m->>'role'='cover')))
 ),facts AS(SELECT jsonb_build_object('official',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY id) FROM official o),'[]'::jsonb),'browser',coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY id) FROM browser b),'[]'::jsonb)) value)
 SELECT jsonb_build_object('entryId',p_entry_id,'confirmedUses',CASE WHEN EXISTS(SELECT 1 FROM refs) OR EXISTS(SELECT 1 FROM entry WHERE is_copy AND source_entry_id IS NOT NULL AND source_entry_id<>id) THEN (SELECT count(*) FROM official WHERE outcome='published') ELSE NULL END,'browserReportedUses',(SELECT count(*) FROM browser WHERE payload->'success'='true'::jsonb),'unknownUses',(SELECT count(*) FROM official WHERE outcome='unknown' OR grant_used AND outcome NOT IN ('published','failed','cancelled'))+(SELECT count(*) FROM browser WHERE NOT has_receipt),'nativeUsageAttribution',CASE WHEN EXISTS(SELECT 1 FROM refs) OR EXISTS(SELECT 1 FROM entry WHERE is_copy AND source_entry_id IS NOT NULL AND source_entry_id<>id) THEN 'entry_provenance' ELSE 'not_recorded' END,'usageFingerprint',encode(sha256(convert_to(value::text,'UTF8')),'hex')) FROM facts
$$;
CREATE FUNCTION public.read_native_media_usage_facts(p_user_id text,p_entry_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE v_id uuid;v_result jsonb:='[]';BEGIN
 PERFORM public.pub_assert_actor(p_user_id);IF coalesce(cardinality(p_entry_ids),0) NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM unnest(p_entry_ids) x WHERE x IS NULL) OR cardinality(p_entry_ids)<>(SELECT count(DISTINCT x) FROM unnest(p_entry_ids) x) THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
 FOREACH v_id IN ARRAY p_entry_ids LOOP PERFORM 1 FROM public.pub_native_media_entries WHERE id=v_id AND owner_id=p_user_id;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;v_result:=v_result||jsonb_build_array(public.native_core_media_usage_facts(p_user_id,v_id));END LOOP;RETURN v_result;
END$$;
CREATE FUNCTION public.mutate_native_core_atomic(p_user_id text,p_input jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_action text:=p_input->>'action';v_request public.pub_native_core_requests%ROWTYPE;v_body jsonb;v_hash text;v_item jsonb;v_row jsonb;v_payload jsonb;v_meta jsonb;v_meta_revision integer;v_result jsonb;v_results jsonb:='[]';v_base_result jsonb;v_id uuid;v_target uuid;v_actual integer;v_revision integer;v_expected integer;v_new_id uuid;v_new_revision integer;v_new_meta_revision integer;v_kind text;v_extra jsonb:='{}';v_save jsonb;v_old_media jsonb:='[]';v_mapping jsonb;v_account_meta public.pub_native_account_meta%ROWTYPE;v_binding public.pub3_account_bindings%ROWTYPE;v_session public.pub3_auth_sessions%ROWTYPE;v_uid text;v_entry public.pub_native_media_entries%ROWTYPE;v_blocked record;v_registered uuid;BEGIN
 PERFORM public.pub_assert_actor(p_user_id);
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR public.pub3_no_credentials(p_input) IS NOT TRUE THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
 IF v_action IN ('archive-drafts','archive-collections','delete-account-groups') THEN PERFORM public.pub2_assert_json_keys(p_input,ARRAY['action','requestKey','requestHash','connectionId','items'],ARRAY['action','requestKey','requestHash','connectionId','items']);
 ELSIF v_action='transfer-drafts' THEN PERFORM public.pub2_assert_json_keys(p_input,ARRAY['action','requestKey','requestHash','connectionId','items','targetCollectionId','expectedTargetCollectionRevision','mode'],ARRAY['action','requestKey','requestHash','connectionId','items','targetCollectionId','expectedTargetCollectionRevision','mode']);
 ELSIF v_action='transfer-content' THEN PERFORM public.pub2_assert_json_keys(p_input,ARRAY['action','requestKey','requestHash','connectionId','items','mediaItems','targetCollectionId','expectedTargetCollectionRevision','mode'],ARRAY['action','requestKey','requestHash','connectionId','items','mediaItems','targetCollectionId','expectedTargetCollectionRevision','mode']);
 ELSIF v_action='save-native-draft' THEN PERFORM public.pub2_assert_json_keys(p_input,ARRAY['action','requestKey','requestHash','connectionId','save','mediaEntryRefs'],ARRAY['action','requestKey','requestHash','connectionId','save','mediaEntryRefs']);
 ELSIF v_action IN ('disconnect-account','reconnect-account') THEN PERFORM public.pub2_assert_json_keys(p_input,ARRAY['action','requestKey','requestHash','connectionId','accountKind','accountId','expectedMetadataRevision','expectedBindingRevision','platformUid','authSessionId'],ARRAY['action','requestKey','requestHash','connectionId','accountKind','accountId','expectedMetadataRevision']);
 ELSIF v_action='archive-media' THEN PERFORM public.pub2_assert_json_keys(p_input,ARRAY['action','requestKey','requestHash','connectionId','items'],ARRAY['action','requestKey','requestHash','connectionId','items']);
 ELSIF v_action='transfer-media' THEN PERFORM public.pub2_assert_json_keys(p_input,ARRAY['action','requestKey','requestHash','connectionId','items','targetCollectionId','expectedTargetCollectionRevision','mode'],ARRAY['action','requestKey','requestHash','connectionId','items','targetCollectionId','expectedTargetCollectionRevision','mode']);
 ELSE RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
 IF jsonb_typeof(p_input->'requestKey') IS DISTINCT FROM 'string' OR length(p_input->>'requestKey') NOT BETWEEN 8 AND 160 OR p_input->>'requestKey' !~ '^[A-Za-z0-9_.:-]+$' OR jsonb_typeof(p_input->'requestHash') IS DISTINCT FROM 'string' OR p_input->>'requestHash' !~ '^[a-f0-9]{64}$' OR jsonb_typeof(p_input->'connectionId') IS DISTINCT FROM 'string' OR length(p_input->>'connectionId') NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
 v_body:=p_input-ARRAY['requestKey','requestHash','connectionId'];v_hash:=encode(sha256(convert_to(v_body::text,'UTF8')),'hex');
 SELECT * INTO v_request FROM public.pub_native_core_requests WHERE owner_id=p_user_id AND request_key=p_input->>'requestKey';
 IF FOUND THEN IF v_request.request_hash IS DISTINCT FROM v_hash THEN RAISE EXCEPTION 'PUBLISH_IDEMPOTENCY_CONFLICT';END IF;RETURN v_request.result||jsonb_build_object('alreadyFulfilled',true);END IF;
 IF v_action='transfer-content' THEN
  IF jsonb_typeof(p_input->'items') IS DISTINCT FROM 'array' OR jsonb_typeof(p_input->'mediaItems') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'items')+jsonb_array_length(p_input->'mediaItems') NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_input->'mediaItems') x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_input->'mediaItems') LOOP
   PERFORM public.pub2_assert_json_keys(v_item,ARRAY['id','expectedRevision'],ARRAY['id','expectedRevision']);IF jsonb_typeof(v_item->'id') IS DISTINCT FROM 'string' OR v_item->>'id' !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(v_item->'expectedRevision') IS DISTINCT FROM 'number' OR v_item->>'expectedRevision' !~ '^[1-9]\d*$' THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
   SELECT revision INTO v_actual FROM public.pub_native_media_entries WHERE id=(v_item->>'id')::uuid AND owner_id=p_user_id AND NOT archived FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;IF v_actual IS DISTINCT FROM (v_item->>'expectedRevision')::integer THEN RAISE EXCEPTION 'NATIVE_CORE_REVISION_CONFLICT';END IF;
  END LOOP;
  IF jsonb_array_length(p_input->'items')>0 THEN v_base_result:=public.mutate_native_core_atomic(p_user_id,(p_input-ARRAY['mediaItems'])||jsonb_build_object('action','transfer-drafts','requestKey','native-transfer-child:'||encode(sha256(convert_to(p_user_id||':'||(p_input->>'requestKey')||':drafts','UTF8')),'hex')));v_results:=v_results||(v_base_result->'items');v_extra:=v_extra||jsonb_build_object('draftItems',v_base_result->'items');END IF;
  IF jsonb_array_length(p_input->'mediaItems')>0 THEN v_base_result:=public.mutate_native_core_atomic(p_user_id,(p_input-ARRAY['mediaItems'])||jsonb_build_object('action','transfer-media','items',p_input->'mediaItems','requestKey','native-transfer-child:'||encode(sha256(convert_to(p_user_id||':'||(p_input->>'requestKey')||':media','UTF8')),'hex')));v_results:=v_results||(v_base_result->'items');v_extra:=v_extra||jsonb_build_object('mediaItems',v_base_result->'items');END IF;
 ELSIF v_action='save-native-draft' THEN
  v_save:=p_input->'save';IF v_save->>'action' IS DISTINCT FROM 'save-draft' THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
  IF jsonb_typeof(p_input->'mediaEntryRefs') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'mediaEntryRefs')>30 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_input->'mediaEntryRefs') x GROUP BY x->>'mediaId' HAVING count(*)>1) THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
  IF v_save->'base' ? 'id' THEN SELECT payload->'media' INTO v_old_media FROM public.pub_native_draft_meta WHERE owner_id=p_user_id AND draft_id=(v_save->'base'->>'id')::uuid AND draft_version=(v_save->'base'->>'expectedRevision')::integer;END IF;
  v_base_result:=public.mutate_native_metadata_atomic(p_user_id,v_save||jsonb_build_object('connectionId',p_input->>'connectionId'));v_row:=v_base_result->'base'->'row';v_id:=(v_row->>'id')::uuid;v_target:=(v_row->'payload'->>'collectionId')::uuid;
  IF v_target IS NOT NULL THEN FOR v_mapping IN SELECT * FROM jsonb_array_elements(v_base_result->'metadata'->'media') LOOP
   v_registered:=NULL;
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(v_old_media,'[]')) x WHERE x->>'assetId'=v_mapping->>'assetId') THEN
    INSERT INTO public.pub_native_media_entries(owner_id,asset_id,collection_id,title) SELECT p_user_id,(v_mapping->>'assetId')::uuid,v_target,a.file_name FROM public.pub3_assets a WHERE a.id=(v_mapping->>'assetId')::uuid AND a.owner_id=p_user_id ON CONFLICT(owner_id,asset_id,collection_id) WHERE NOT is_copy AND NOT archived DO NOTHING RETURNING id INTO v_registered;
   END IF;
   IF v_registered IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_input->'mediaEntryRefs') x WHERE x->>'mediaId'=v_mapping->>'mediaId') THEN INSERT INTO public.pub_native_media_usage_refs(owner_id,draft_id,draft_version,media_id,media_entry_id) VALUES(p_user_id,v_id,(v_row->>'revision')::integer,(v_mapping->>'mediaId')::uuid,v_registered);END IF;
  END LOOP;END IF;
  FOR v_mapping IN SELECT * FROM jsonb_array_elements(p_input->'mediaEntryRefs') LOOP
   PERFORM public.pub2_assert_json_keys(v_mapping,ARRAY['mediaId','mediaEntryId'],ARRAY['mediaId','mediaEntryId']);IF jsonb_typeof(v_mapping->'mediaId') IS DISTINCT FROM 'string' OR v_mapping->>'mediaId' !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(v_mapping->'mediaEntryId') IS DISTINCT FROM 'string' OR v_mapping->>'mediaEntryId' !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
   SELECT * INTO v_entry FROM public.pub_native_media_entries WHERE id=(v_mapping->>'mediaEntryId')::uuid AND owner_id=p_user_id AND NOT archived FOR SHARE;IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_base_result->'metadata'->'media') x WHERE x->>'mediaId'=v_mapping->>'mediaId' AND x->>'assetId'=v_entry.asset_id::text) THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;
   INSERT INTO public.pub_native_media_usage_refs(owner_id,draft_id,draft_version,media_id,media_entry_id) VALUES(p_user_id,v_id,(v_row->>'revision')::integer,(v_mapping->>'mediaId')::uuid,v_entry.id);
  END LOOP;
  IF v_save->'base' ? 'id' THEN INSERT INTO public.pub_native_media_usage_refs(owner_id,draft_id,draft_version,media_id,media_entry_id) SELECT p_user_id,v_id,(v_row->>'revision')::integer,r.media_id,r.media_entry_id FROM public.pub_native_media_usage_refs r JOIN public.pub_native_media_entries e ON e.id=r.media_entry_id AND e.owner_id=p_user_id WHERE r.owner_id=p_user_id AND r.draft_id=(v_save->'base'->>'id')::uuid AND r.draft_version=(v_save->'base'->>'expectedRevision')::integer AND EXISTS(SELECT 1 FROM jsonb_array_elements(v_base_result->'metadata'->'media') x WHERE x->>'mediaId'=r.media_id::text AND x->>'assetId'=e.asset_id::text) AND NOT EXISTS(SELECT 1 FROM public.pub_native_media_usage_refs n WHERE n.draft_id=v_id AND n.draft_version=(v_row->>'revision')::integer AND n.media_id=r.media_id);END IF;
  v_results:=jsonb_build_array(jsonb_build_object('id',v_id,'revision',v_row->'revision','metadataRevision',v_base_result->'metadataRevision'));v_extra:=v_base_result;
 ELSIF v_action IN ('disconnect-account','reconnect-account') THEN
  IF jsonb_typeof(p_input->'accountId') IS DISTINCT FROM 'string' OR p_input->>'accountId' !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(p_input->'accountKind') IS DISTINCT FROM 'string' OR p_input->>'accountKind' NOT IN ('browser','official') OR jsonb_typeof(p_input->'expectedMetadataRevision') IS DISTINCT FROM 'number' OR p_input->>'expectedMetadataRevision' !~ '^\d+$' THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
  v_id:=(p_input->>'accountId')::uuid;v_kind:=p_input->>'accountKind';
  IF v_kind='browser' THEN SELECT platform_account_id INTO v_uid FROM public.pub_accounts WHERE id=v_id AND user_id=p_user_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;IF p_input ? 'expectedBindingRevision' OR p_input ? 'authSessionId' THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
  ELSE
   SELECT * INTO v_binding FROM public.pub3_account_bindings WHERE id=v_id AND owner_id=p_user_id AND connection_id=p_input->>'connectionId' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;
   IF jsonb_typeof(p_input->'expectedBindingRevision') IS DISTINCT FROM 'number' OR p_input->>'expectedBindingRevision' !~ '^[1-9]\d*$' THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;IF v_binding.revision IS DISTINCT FROM (p_input->>'expectedBindingRevision')::integer THEN RAISE EXCEPTION 'NATIVE_CORE_REVISION_CONFLICT';END IF;
  END IF;
  SELECT * INTO v_account_meta FROM public.pub_native_account_meta WHERE owner_id=p_user_id AND account_kind=v_kind AND account_id=v_id FOR UPDATE;IF coalesce(v_account_meta.revision,0) IS DISTINCT FROM (p_input->>'expectedMetadataRevision')::integer THEN RAISE EXCEPTION 'NATIVE_CORE_REVISION_CONFLICT';END IF;
  IF v_action='reconnect-account' THEN
   IF v_account_meta.disconnected IS NOT TRUE THEN RAISE EXCEPTION 'NATIVE_CORE_RECONNECT_EVIDENCE_INVALID';END IF;
   IF v_kind='browser' THEN IF jsonb_typeof(p_input->'platformUid') IS DISTINCT FROM 'string' OR p_input->>'platformUid' IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'NATIVE_CORE_RECONNECT_EVIDENCE_INVALID';END IF;
   ELSE
    IF jsonb_typeof(p_input->'authSessionId') IS DISTINCT FROM 'string' OR p_input->>'authSessionId' !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR p_input ? 'platformUid' THEN RAISE EXCEPTION 'NATIVE_CORE_RECONNECT_EVIDENCE_INVALID';END IF;
    SELECT * INTO v_session FROM public.pub3_auth_sessions WHERE id=(p_input->>'authSessionId')::uuid AND owner_id=p_user_id AND connection_id=v_binding.connection_id AND platform=v_binding.platform AND state='completed';IF NOT FOUND OR v_binding.auth_session_id IS DISTINCT FROM v_session.id OR v_binding.status<>'active' OR v_account_meta.disconnected_at IS NULL OR v_session.created_at<=v_account_meta.disconnected_at THEN RAISE EXCEPTION 'NATIVE_CORE_RECONNECT_EVIDENCE_INVALID';END IF;
   END IF;
  ELSIF p_input ? 'platformUid' OR p_input ? 'authSessionId' THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
  INSERT INTO public.pub_native_account_meta(owner_id,account_kind,account_id,group_id,rank,revision,disconnected,disconnected_at) VALUES(p_user_id,v_kind,v_id,v_account_meta.group_id,coalesce(v_account_meta.rank,0),coalesce(v_account_meta.revision,0)+1,v_action='disconnect-account',CASE WHEN v_action='disconnect-account' THEN now() ELSE NULL END) ON CONFLICT(owner_id,account_kind,account_id) DO UPDATE SET revision=EXCLUDED.revision,disconnected=EXCLUDED.disconnected,disconnected_at=EXCLUDED.disconnected_at,updated_at=now() RETURNING * INTO v_account_meta;
  IF v_action='disconnect-account' AND v_kind='official' THEN FOR v_blocked IN UPDATE public.pub3_operations SET dispatch_state='blocked',outcome='pending',error_code='NATIVE_ACCOUNT_DISCONNECTED',revision=revision+1,updated_at=now() WHERE owner_id=p_user_id AND kind='publish' AND snapshot->'binding'->>'id'=v_id::text AND dispatch_state IN ('ready','dispatching') AND NOT grant_used AND provider_record_id IS NULL AND provider_task_id IS NULL RETURNING id LOOP INSERT INTO public.pub3_events(owner_id,operation_id,kind,source,safe_payload) VALUES(p_user_id,v_blocked.id,'blocked','system','{"status":"blocked","errorCode":"NATIVE_ACCOUNT_DISCONNECTED"}');END LOOP;END IF;
  v_results:=jsonb_build_array(jsonb_build_object('id',v_id,'accountKind',v_kind,'metadataRevision',v_account_meta.revision,'disconnected',v_account_meta.disconnected));
  INSERT INTO public.pub_native_meta_events(owner_id,entity_kind,entity_id,revision,payload_hash,safe_snapshot) VALUES(p_user_id,'account',v_id,v_account_meta.revision,encode(sha256(convert_to(v_results::text,'UTF8')),'hex'),v_results);
 ELSE
 IF jsonb_typeof(p_input->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'items') NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_input->'items') x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
 IF v_action IN ('transfer-drafts','transfer-media') THEN
  IF jsonb_typeof(p_input->'mode') IS DISTINCT FROM 'string' OR p_input->>'mode' NOT IN ('move','copy') OR jsonb_typeof(p_input->'targetCollectionId') IS DISTINCT FROM 'string' OR p_input->>'targetCollectionId' !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(p_input->'expectedTargetCollectionRevision') IS DISTINCT FROM 'number' OR p_input->>'expectedTargetCollectionRevision' !~ '^[1-9]\d*$' THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
  v_target:=(p_input->>'targetCollectionId')::uuid;SELECT revision INTO v_actual FROM public.pub2_collections WHERE id=v_target AND user_id=p_user_id AND NOT archived FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;IF v_actual IS DISTINCT FROM (p_input->>'expectedTargetCollectionRevision')::integer THEN RAISE EXCEPTION 'NATIVE_CORE_REVISION_CONFLICT';END IF;
 END IF;
 -- Complete every owner and CAS check before applying the first member-visible change.
 FOR v_item IN SELECT * FROM jsonb_array_elements(p_input->'items') LOOP
  IF v_action IN ('archive-media','transfer-media') THEN PERFORM public.pub2_assert_json_keys(v_item,ARRAY['id','expectedRevision'],ARRAY['id','expectedRevision']);ELSE PERFORM public.pub2_assert_json_keys(v_item,ARRAY['id','expectedRevision','expectedMetadataRevision','expectedUsageFingerprint'],ARRAY['id','expectedRevision','expectedMetadataRevision']);END IF;
  IF jsonb_typeof(v_item->'id') IS DISTINCT FROM 'string' OR v_item->>'id' !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(v_item->'expectedRevision') IS DISTINCT FROM 'number' OR v_item->>'expectedRevision' !~ '^[1-9]\d*$' OR v_action NOT IN ('archive-media','transfer-media') AND (jsonb_typeof(v_item->'expectedMetadataRevision') IS DISTINCT FROM 'number' OR v_item->>'expectedMetadataRevision' !~ '^\d+$') THEN RAISE EXCEPTION 'NATIVE_CORE_INPUT_INVALID';END IF;
  v_id:=(v_item->>'id')::uuid;v_expected:=(v_item->>'expectedRevision')::integer;v_meta_revision:=0;
  IF v_action IN ('archive-drafts','transfer-drafts') THEN SELECT revision INTO v_actual FROM public.pub2_drafts WHERE id=v_id AND user_id=p_user_id AND NOT archived FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;SELECT revision INTO v_meta_revision FROM public.pub_native_draft_meta WHERE draft_id=v_id AND draft_version=v_actual AND owner_id=p_user_id;
  ELSIF v_action='archive-collections' THEN SELECT revision INTO v_actual FROM public.pub2_collections WHERE id=v_id AND user_id=p_user_id AND NOT archived FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;SELECT revision INTO v_meta_revision FROM public.pub_native_collection_meta WHERE collection_id=v_id AND owner_id=p_user_id FOR UPDATE;
  ELSIF v_action='delete-account-groups' THEN SELECT revision INTO v_actual FROM public.pub2_groups WHERE id=v_id AND user_id=p_user_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;SELECT revision INTO v_meta_revision FROM public.pub_native_group_meta WHERE group_id=v_id AND owner_id=p_user_id FOR UPDATE;
  ELSE SELECT revision INTO v_actual FROM public.pub_native_media_entries WHERE id=v_id AND owner_id=p_user_id AND NOT archived FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NATIVE_CORE_OWNER_MISMATCH';END IF;END IF;
  IF v_actual IS DISTINCT FROM v_expected OR v_action NOT IN ('archive-media','transfer-media') AND coalesce(v_meta_revision,0) IS DISTINCT FROM (v_item->>'expectedMetadataRevision')::integer THEN RAISE EXCEPTION 'NATIVE_CORE_REVISION_CONFLICT';END IF;
  IF v_item ? 'expectedUsageFingerprint' THEN IF v_action<>'archive-drafts' OR jsonb_typeof(v_item->'expectedUsageFingerprint') IS DISTINCT FROM 'string' OR v_item->>'expectedUsageFingerprint' !~ '^[a-f0-9]{64}$' OR (public.native_core_usage_facts(p_user_id,v_id)->>'usageFingerprint') IS DISTINCT FROM v_item->>'expectedUsageFingerprint' THEN RAISE EXCEPTION 'NATIVE_CORE_USAGE_CHANGED';END IF;END IF;
 END LOOP;
 FOR v_item IN SELECT * FROM jsonb_array_elements(p_input->'items') LOOP
  v_id:=(v_item->>'id')::uuid;v_revision:=(v_item->>'expectedRevision')::integer;v_meta_revision:=(v_item->>'expectedMetadataRevision')::integer;v_new_meta_revision:=v_meta_revision;v_new_id:=v_id;v_meta:=NULL;
  IF v_action='archive-drafts' THEN
   SELECT payload INTO v_payload FROM public.pub2_draft_versions WHERE draft_id=v_id AND version=v_revision AND user_id=p_user_id;SELECT payload INTO v_meta FROM public.pub_native_draft_meta WHERE draft_id=v_id AND draft_version=v_revision AND owner_id=p_user_id;
   UPDATE public.pub2_drafts SET archived=true,revision=revision+1,updated_at=now() WHERE id=v_id AND user_id=p_user_id RETURNING revision INTO v_new_revision;INSERT INTO public.pub2_draft_versions(user_id,draft_id,version,payload) VALUES(p_user_id,v_id,v_new_revision,v_payload);
   IF v_meta IS NOT NULL THEN v_new_meta_revision:=v_meta_revision+1;INSERT INTO public.pub_native_draft_meta(draft_id,draft_version,owner_id,revision,payload) VALUES(v_id,v_new_revision,p_user_id,v_new_meta_revision,v_meta);END IF;
  ELSIF v_action='transfer-drafts' THEN
   SELECT payload INTO v_payload FROM public.pub2_draft_versions WHERE draft_id=v_id AND version=v_revision AND user_id=p_user_id;SELECT payload INTO v_meta FROM public.pub_native_draft_meta WHERE draft_id=v_id AND draft_version=v_revision AND owner_id=p_user_id;
   v_payload:=jsonb_set(v_payload,'{collectionId}',to_jsonb(v_target));IF p_input->>'mode'='move' THEN UPDATE public.pub2_drafts SET collection_id=v_target,revision=revision+1,updated_at=now() WHERE id=v_id AND user_id=p_user_id RETURNING revision INTO v_new_revision;ELSE INSERT INTO public.pub2_drafts(user_id,collection_id) VALUES(p_user_id,v_target) RETURNING id,revision INTO v_new_id,v_new_revision;END IF;INSERT INTO public.pub2_draft_versions(user_id,draft_id,version,payload) VALUES(p_user_id,v_new_id,v_new_revision,v_payload);
   IF v_meta IS NOT NULL THEN v_new_meta_revision:=CASE WHEN p_input->>'mode'='copy' THEN 1 ELSE v_meta_revision+1 END;INSERT INTO public.pub_native_draft_meta(draft_id,draft_version,owner_id,revision,payload) VALUES(v_new_id,v_new_revision,p_user_id,v_new_meta_revision,v_meta);INSERT INTO public.pub_native_meta_events(owner_id,entity_kind,entity_id,entity_version,revision,payload_hash,safe_snapshot) VALUES(p_user_id,'draft',v_new_id,v_new_revision,v_new_meta_revision,encode(sha256(convert_to(v_meta::text,'UTF8')),'hex'),v_meta);END IF;
  ELSIF v_action='archive-collections' THEN
   SELECT to_jsonb(c) INTO v_row FROM public.pub2_collections c WHERE id=v_id AND user_id=p_user_id;SELECT payload INTO v_meta FROM public.pub_native_collection_meta WHERE collection_id=v_id AND owner_id=p_user_id;
   v_base_result:=public.mutate_native_metadata_atomic(p_user_id,jsonb_build_object('action','save-collection','connectionId',p_input->>'connectionId','base',jsonb_build_object('action','save-collection','id',v_id,'expectedRevision',v_revision,'name',v_row->'name','description',v_row->'description','archived',true),'expectedMetadataRevision',v_meta_revision,'metadata',coalesce(v_meta,'{"schemaVersion":1,"platforms":[],"useScene":null,"useSceneRelId":null}'::jsonb)));v_new_revision:=(v_base_result->'base'->'row'->>'revision')::integer;v_new_meta_revision:=v_meta_revision+1;
  ELSIF v_action='delete-account-groups' THEN v_base_result:=public.mutate_publish_v2_atomic(p_user_id,jsonb_build_object('action','delete-group','id',v_id,'expectedRevision',v_revision));v_new_revision:=v_revision;
  ELSIF v_action='archive-media' THEN UPDATE public.pub_native_media_entries SET archived=true,revision=revision+1,updated_at=now() WHERE id=v_id AND owner_id=p_user_id RETURNING revision INTO v_new_revision;
  ELSE SELECT * INTO v_entry FROM public.pub_native_media_entries WHERE id=v_id AND owner_id=p_user_id;IF p_input->>'mode'='copy' THEN INSERT INTO public.pub_native_media_entries(owner_id,asset_id,collection_id,title,is_copy,source_entry_id) VALUES(p_user_id,v_entry.asset_id,v_target,v_entry.title,true,v_entry.id) RETURNING id,revision INTO v_new_id,v_new_revision;ELSE UPDATE public.pub_native_media_entries SET collection_id=v_target,revision=revision+1,updated_at=now(),is_copy=v_entry.is_copy OR EXISTS(SELECT 1 FROM public.pub_native_media_entries x WHERE x.owner_id=p_user_id AND x.asset_id=v_entry.asset_id AND x.collection_id=v_target AND x.id<>v_id AND NOT x.archived AND NOT x.is_copy) WHERE id=v_id AND owner_id=p_user_id RETURNING revision INTO v_new_revision;END IF;END IF;
  v_results:=v_results||jsonb_build_array(jsonb_build_object('id',v_new_id,'sourceId',v_id,'revision',v_new_revision,'metadataRevision',v_new_meta_revision));
  IF v_action IN ('archive-drafts','transfer-drafts') THEN INSERT INTO public.pub_native_media_usage_refs(owner_id,draft_id,draft_version,media_id,media_entry_id) SELECT p_user_id,v_new_id,v_new_revision,media_id,media_entry_id FROM public.pub_native_media_usage_refs WHERE owner_id=p_user_id AND draft_id=v_id AND draft_version=v_revision;END IF;
 END LOOP;
 END IF;
 v_result:=jsonb_build_object('ok',true,'count',jsonb_array_length(v_results),'items',v_results,'alreadyFulfilled',false)||v_extra;
 INSERT INTO public.pub_native_core_requests(owner_id,request_key,request_hash,request_payload,result) VALUES(p_user_id,p_input->>'requestKey',v_hash,v_body,v_result) RETURNING * INTO v_request;
 INSERT INTO public.pub_native_core_events(owner_id,request_id,kind,safe_snapshot) VALUES(p_user_id,v_request.id,v_action,v_result);
 RETURN v_result;
END$$;
REVOKE ALL ON FUNCTION public.mutate_native_core_atomic(text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.native_assert_account_connected() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.native_core_usage_facts(text,uuid) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.read_native_usage_facts(text,uuid[]) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.native_core_media_usage_facts(text,uuid) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.read_native_media_usage_facts(text,uuid[]) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.mutate_native_core_atomic(text,jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.read_native_usage_facts(text,uuid[]) TO service_role;
GRANT EXECUTE ON FUNCTION public.read_native_media_usage_facts(text,uuid[]) TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;
